/**
 * Zwraca wynik `require(...)` dla audio MP3 dla danego voiceKey,
 * lub `null` jeśli nie ma takiego klucza w manifescie.
 */
export function voiceFor(voiceKey: string): number | null {
  const hash = VOICE_LOOKUP[voiceKey];
  return hash ? (VOICE_FILES[hash] ?? null) : null;
}
